package com.hms.website;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="website_theme_snapshots") public class WebsiteThemeSnapshot { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(length=500) private String logoUrl; @Column(length=20) private String primaryColor; @Column(length=20) private String secondaryColor; @Column(length=100) private String fontFamily; @Column(length=300) private String tagline; @Column(length=40) private String contactPhone; @Column(length=180) private String contactEmail; @Column(length=500) private String address; @Column(length=500) private String facebookUrl; @Column(length=500) private String instagramUrl; @Column(length=500) private String youtubeUrl; @Column(nullable=false) private OffsetDateTime createdAt; protected WebsiteThemeSnapshot(){} public WebsiteThemeSnapshot(UUID tenantId,WebsiteSettings s){this.id=UUID.randomUUID();this.tenantId=tenantId;logoUrl=s.getLogoUrl();primaryColor=s.getPrimaryColor();secondaryColor=s.getSecondaryColor();fontFamily=s.getFontFamily();tagline=s.getTagline();contactPhone=s.getContactPhone();contactEmail=s.getContactEmail();address=s.getAddress();facebookUrl=s.getFacebookUrl();instagramUrl=s.getInstagramUrl();youtubeUrl=s.getYoutubeUrl();createdAt=OffsetDateTime.now();} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getLogoUrl(){return logoUrl;} public String getPrimaryColor(){return primaryColor;} public String getSecondaryColor(){return secondaryColor;} public String getFontFamily(){return fontFamily;} public String getTagline(){return tagline;} public String getContactPhone(){return contactPhone;} public String getContactEmail(){return contactEmail;} public String getAddress(){return address;} public String getFacebookUrl(){return facebookUrl;} public String getInstagramUrl(){return instagramUrl;} public String getYoutubeUrl(){return youtubeUrl;} public OffsetDateTime getCreatedAt(){return createdAt;} public UpdateWebsiteSettingsRequest request(){return new UpdateWebsiteSettingsRequest(logoUrl,primaryColor,secondaryColor,fontFamily,tagline,contactPhone,contactEmail,address,facebookUrl,instagramUrl,youtubeUrl,true);} }
